// A pet body is first-party static markup compiled into the binary, but it is the
// ONE string in this file that reaches innerHTML, and these definitions are bulk-
// authored — so it is validated here rather than trusted. A definition that fails
// is dropped entirely (never rendered), so the innerHTML below can only ever
// receive a string that passed this gate. Allowlist the handful of SVG primitives
// a pet actually needs; reject every element or attribute that can load, script,
// or reference anything external.
var SVG_ALLOWED = /^<svg[\s>][\s\S]*<\/svg>$/i;
var SVG_FORBIDDEN = /<\s*(script|foreignObject|image|use|iframe|object|embed|animate|set|handler|a)\b|javascript:|data:(?!image\/)|\son\w+\s*=|url\s*\(|xlink:href|href\s*=|<!--|<!\[CDATA/i;
function svgIsSafe(s) {
  if (typeof s !== 'string') return false;
  var t = s.trim();
  if (t.length < 20 || t.length > 4000) return false;
  if (!SVG_ALLOWED.test(t)) return false;
  if (SVG_FORBIDDEN.test(t)) return false;
  return true;
}

var BY_ID = Object.create(null);
(function indexPets() {
  for (var i = 0; i < PETS.length; i++) {
    var d = PETS[i];
    if (!d || !d.id || !/^[a-z][a-z0-9_]*$/.test(d.id)) continue;
    if (BY_ID[d.id]) continue;                    // first definition wins
    if (!svgIsSafe(d.svg)) continue;
    BY_ID[d.id] = d;
  }
})();

// ── public API ──────────────────────────────────────────────────────────────
function enable(id) {
  if (_reduced) return false;
  var def = BY_ID[id];
  if (!def || _active[id]) return false;
  var n = 0; for (var k in _active) n++;
  if (n >= MAX_ACTIVE) return false;
  var p = new Pet(def);
  _active[id] = p;
  p.mount();
  syncVisibility();
  return true;
}
function disable(id) {
  var p = _active[id];
  if (!p) return false;
  delete _active[id];
  p.destroy();
  syncVisibility();
  return true;
}
function disableAll() { for (var id in _active) disable(id); }

// Reconcile the whole set in one call — what app.js's apply funnel uses, so it
// stays idempotent no matter how often it runs.
function setActive(ids) {
  var want = Object.create(null), i, id;
  if (Object.prototype.toString.call(ids) === '[object Array]') {
    for (i = 0; i < ids.length && i < MAX_ACTIVE; i++) if (BY_ID[ids[i]]) want[ids[i]] = 1;
  }
  for (id in _active) if (!want[id]) disable(id);
  for (id in want) if (!_active[id]) enable(id);
}

window.CryptIRCPets = {
  enable: enable,
  disable: disable,
  disableAll: disableAll,
  setActive: setActive,
  isOn: function (id) { return !!_active[id]; },
  list: function () {
    var out = [], id;
    for (id in BY_ID) out.push({ id: id, name: BY_ID[id].name, emoji: BY_ID[id].emoji, blurb: BY_ID[id].blurb || '' });
    out.sort(function (a, b) { return a.name < b.name ? -1 : a.name > b.name ? 1 : 0; });
    return out;
  },
  MAX_ACTIVE: MAX_ACTIVE
};

